function Sky(id)
    e = char.HumanoidRootPart.CFrame.x
    f = char.HumanoidRootPart.CFrame.y
    g = char.HumanoidRootPart.CFrame.z
    CreatePart(CFrame.new(math.floor(e),math.floor(f),math.floor(g)) + Vector3.new(0,-9,0),workspace.Terrain)
    wait(0.5) -- Increased wait time for part creation
    for i,v in game.Workspace:GetDescendants() do
        if v:IsA("BasePart") and v.CFrame.x == math.floor(e) and v.CFrame.z == math.floor(g) then
            SetName(v,"Sky")
            AddMesh(v)
            SetMesh(v,"111891702759441")
            SetTexture(v,id)
            MeshResize(v,Vector3.new(20000, 20000, 20000))
            VertexColormf(v)
            SetLocked(v,true)


            local skyPart = v
            local rotationSpeedX = 50
            local rotationSpeedZ = 50
            local rotationSpeedY = 50
            local currentRotation = Vector3.new(0, 0, 0)

            game:GetService("RunService").Heartbeat:Connect(function(deltaTime)
                currentRotation = Vector3.new(
                    (currentRotation.X + rotationSpeedX * deltaTime) % 360,
                    (currentRotation.Y + rotationSpeedY * deltaTime) % 360,
                    (currentRotation.Z + rotationSpeedZ * deltaTime) % 360
                )


                local baseCFrame = CFrame.new(skyPart.Position)
                local rotatedCFrame = baseCFrame * CFrame.Angles(
                    math.rad(currentRotation.X),
                    math.rad(currentRotation.Y),
                    math.rad(currentRotation.Z)
                )

                MovePart(skyPart, rotatedCFrame)
            end)

            break
        end
    end
end

Sky("80707942259907")
